from fastapi.responses import HTMLResponse

HTML = '''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HaberRSS Control</title><style>body{font-family:system-ui;background:#0b0d12;color:#eee;margin:0;padding:24px}h1{margin:0 0 20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}.card{background:#151922;border:1px solid #252b38;border-radius:14px;padding:16px}.num{font-size:30px;font-weight:800}.muted{color:#9299a8;font-size:13px}table{width:100%;border-collapse:collapse;margin-top:20px;background:#11151d;border-radius:12px;overflow:hidden}th,td{text-align:left;padding:10px;border-bottom:1px solid #242936;font-size:14px}a{color:#8ab4ff}.score{font-weight:800}.breaking{color:#ff6b6b}</style></head><body><h1>HaberRSS / Control Center</h1><div id="cards" class="grid"></div><h2>Canlı Gündem</h2><table><thead><tr><th>Skor</th><th>Konu</th><th>Kategori</th><th>Haber</th><th>Kaynak</th><th>Durum</th></tr></thead><tbody id="trends"></tbody></table><script>const token=localStorage.getItem('haber_admin_token')||prompt('ADMIN_TOKEN');if(token)localStorage.setItem('haber_admin_token',token);const H={'X-Admin-Token':token};async function load(){const o=await fetch('/api/admin/overview',{headers:H}).then(r=>r.json());document.getElementById('cards').innerHTML=Object.entries(o).map(([k,v])=>`<div class="card"><div class="muted">${k.replaceAll('_',' ')}</div><div class="num">${v}</div></div>`).join('');const t=await fetch('/api/admin/breaking?limit=50',{headers:H}).then(r=>r.json());document.getElementById('trends').innerHTML=t.map(x=>`<tr><td class="score ${x.viral_score>=75?'breaking':''}">${Number(x.viral_score).toFixed(1)}</td><td>${x.canonical_title}</td><td>${x.category||''}</td><td>${x.article_count}</td><td>${x.source_count}</td><td>${x.state}</td></tr>`).join('')}load();setInterval(load,10000)</script></body></html>'''

def dashboard(): return HTMLResponse(HTML)
